head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > M > reform]<br/>DataList 모듈의 원본(Origin) 데이터가 제거되고 현재 데이터를 새로운 원본(Origin) 데이터로 재설정합니다",
    "validation" : [
        "필터링/정렬이 적용 되지 않은 상태를 기준으로 현재 데이터가 원본(Origin) 데이터로 저장됩니다.",
        "원본(Origin) 데이터는 DataList 모듈에 최초로 로딩된 데이터를 의미합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createBasicDataList();

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true"', '', 'gridView1');
}   



scwin.btn_setCellData_onclick = function (e) {
    target1.setCellData(2, "col1", "change");
};



scwin.btn_getAllJSON_onclick = function (e) {
    let rtn = target1.getAllJSON();
    let jsonString = JSON.stringify(rtn);

	wf_body_bottom.getObj("scwin").setReturnValue("result: " + rtn);
	wf_body_bottom.getObj("scwin").setReturnValue("result.json: " + jsonString);
};



scwin.btn_reform_onclick = function (e) {
    target1.reform();    
};



scwin.btn_undoAll_onclick = function (e) {
	target1.undoAll();

    scwin.btn_getAllJSON_onclick();

    scwin.btn_getDeletedArray_onclick();
};
